  external int backend;
}

/// struct_size: người gọi điền sizeof(tc_metrics) của header họ dùng; engine chỉ ghi phần
/// nằm trong struct_size → binding cũ (v0.1) vẫn dùng được.
final class tc_metrics extends ffi.Struct {
  @ffi.Uint32()
  external int struct_size;

  /// tc_engine_state
  @ffi.Int32()
  external int state;

  @ffi.Uint32()
  external int sample_rate;

  /// tổng số frame đã xử lý
  @ffi.Uint64()
  external int frames_processed;

  /// số lần gọi xử lý
  @ffi.Uint64()
  external int callbacks;

  /// số lần thiếu/tràn buffer
  @ffi.Uint32()
  external int xruns;

  /// 0..1 – tỉ lệ thời gian xử lý / thời lượng block gần nhất
  @ffi.Float()
  external double cpu_load;

  /// kích thước buffer đầu ra hiện tại
  @ffi.Uint32()
  external int buffer_frames;

  /// số frame mỗi lần callback của thiết bị
  @ffi.Uint32()
  external int burst_frames;

  /// độ trễ vào do hệ điều hành báo (ước lượng)
  @ffi.Double()
  external double reported_input_latency_ms;

  /// độ trễ ra do hệ điều hành báo (ước lượng)
  @ffi.Double()
  external double reported_output_latency_ms;

  /// tc_route
  @ffi.Int32()
  external int route;

  /// tc_audio_api
  @ffi.Int32()
  external int audio_api;

  /// 1 nếu đang nghe lại giọng
  @ffi.Int32()
  external int monitor_active;

  /// số kênh micro thực tế
  @ffi.Int32()
  external int input_channels;

  /// 0..1 – tải cao nhất trong 1 giây gần nhất
  @ffi.Float()
  external double cpu_load_peak;

  /// độ trễ thêm do xử lý (480 khi bật chỉnh giọng ở 48 kHz)
  @ffi.Int32()
  external int algorithm_latency_frames;
}

final class tc_playback_state extends ffi.Struct {
  @ffi.Uint32()
  external int struct_size;

  @ffi.Int32()
  external int has_beat;

  @ffi.Int32()
  external int playing;

  @ffi.Double()
  external double position_ms;

  @ffi.Double()
  external double duration_ms;
}

final class tc_latency_result extends ffi.Struct {
  @ffi.Uint32()
  external int struct_size;

  /// 1 nếu đo thành công
  @ffi.Int32()
  external int valid;

  /// round-trip đo được (trung vị)
  @ffi.Double()
  external double latency_ms;

  @ffi.Double()
  external double latency_frames;

  /// 0..1
  @ffi.Float()
  external double confidence;

  /// số lần đo hợp lệ
  @ffi.Int32()
  external int valid_bursts;

  @ffi.Int32()
  external int total_bursts;

  /// chênh lệch giữa các lần hợp lệ
  @ffi.Double()
  external double spread_ms;

  /// HĐH báo lúc đo, để so sánh
  @ffi.Double()
  external double reported_input_latency_ms;

  @ffi.Double()
  external double reported_output_latency_ms;

  @ffi.Uint32()
  external int buffer_frames;

  @ffi.Uint32()
  external int burst_frames;

  @ffi.Int32()
  external int route;
}

/// Trạng thái cao độ cho đồng hồ cao độ (từ v0.3).
final class tc_pitch_state extends ffi.Struct {
  @ffi.Uint32()
  external int struct_size;

  /// 1 nếu đang có giọng hát
  @ffi.Int32()
  external int voiced;

  /// cao độ người hát (Hz), 0 khi không có giọng
  @ffi.Float()
  external double f0_hz;

  /// 0..1
  @ffi.Float()
  external double confidence;

  /// cao độ người hát dạng số MIDI thực (69 = La 440 Hz)
  @ffi.Float()
  external double input_note;

  /// nốt đích (MIDI), -1 nếu chưa có
  @ffi.Int32()
  external int target_note;

  /// người hát lệch bao nhiêu cent so với nốt đích
  @ffi.Float()
  external double cents_off;

  /// engine đang dịch bao nhiêu cent
  @ffi.Float()
  external double correction_cents;

  /// 1 nếu tự chỉnh giọng đang bật
  @ffi.Int32()
  external int enabled;
}

final class tc_event extends ffi.Struct {
  /// tc_event_type
  @ffi.Int32()
  external int type;

  @ffi.Int32()
  external int code;

  @ffi.Double()
  external double value;
}

const int TC_API_VERSION_MAJOR = 0;

const int TC_API_VERSION_MINOR = 3;

const int TC_API_VERSION_PATCH = 0;

const int TC_API_VERSION = 768;
